def f(g):
    A=[[int(x) for x in row] for row in g]
    ys=[i for i,row in enumerate(A) for j,x in enumerate(row) if x==8]; xs=[j for i,row in enumerate(A) for j,x in enumerate(row) if x==8]
    P=[[A[r][c] for c in range(min(xs),max(xs)+1)] for r in range(min(ys),max(ys)+1)]
